import { Ionicons } from "@expo/vector-icons";
import { useQuery } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, useWindowDimensions, View } from "react-native";
import { useAuthStore } from "../../src/features/auth/auth.store";
import { useCurrentUser } from "../../src/features/auth/use-current-user";
import { getVendorReport, getVendorWorkspace } from "../../src/features/vendor/vendor.api";
import { Screen } from "../../src/ui/Screen";
import { formatMinor } from "../../src/ui/money";
import { colors, radius, spacing } from "../../src/ui/tokens";

export default function VendorDashboardScreen() {
  const router = useRouter();
  const compact = useWindowDimensions().width < 720;
  const user = useCurrentUser();
  const session = useAuthStore((state) => state.session);
  const enabled = Boolean(user && session?.vendorMemberships.length);
  const workspace = useQuery({ queryKey: ["vendor", "workspace", user?.uid], queryFn: () => getVendorWorkspace(user!), enabled });
  const report = useQuery({ queryKey: ["vendor", "report", user?.uid], queryFn: () => getVendorReport(user!), enabled });

  if (!session?.vendorMemberships.length) return <Screen title="Seller registration required" description="Create a seller workspace before opening seller operations."><Pressable onPress={() => router.replace("/vendor/register")} style={styles.primary}><Text style={styles.primaryText}>Start seller registration</Text></Pressable></Screen>;

  const shop = workspace.data?.shops[0];
  const completedOrders = ["DELIVERED", "REJECTED", "CANCELLED", "REFUNDED"].reduce((sum, status) => sum + (report.data?.statusCounts[status] ?? 0), 0);
  const activeOrders = Math.max(0, (report.data?.orderCount ?? 0) - completedOrders);
  const pendingOrders = ["PENDING", "PLACED", "CONFIRMED", "PROCESSING"].reduce((sum, status) => sum + (report.data?.statusCounts[status] ?? 0), 0);
  const setup = [workspace.data?.status === "APPROVED", shop?.status === "ACTIVE", workspace.data?.kycSubmissions[0]?.status === "APPROVED", Boolean(workspace.data?.bankAccounts.length)];
  const readiness = Math.round((setup.filter(Boolean).length / setup.length) * 100);
  const actions = [
    ...(pendingOrders ? [{ title: "Orders need processing", detail: `${pendingOrders} order${pendingOrders === 1 ? "" : "s"} waiting for seller action`, href: "/vendor/orders", icon: "bag-handle-outline" as const, urgent: true }] : []),
    ...(Number(report.data?.lowStockCount ?? 0) ? [{ title: "Low stock products", detail: `${report.data?.lowStockCount} listing${report.data?.lowStockCount === 1 ? "" : "s"} need inventory updates`, href: "/vendor/inventory", icon: "warning-outline" as const, urgent: true }] : []),
    ...(!setup[2] ? [{ title: "Complete KYC verification", detail: "Submit seller identity documents", href: "/vendor/kyc", icon: "shield-checkmark-outline" as const, urgent: false }] : []),
    ...(!setup[3] ? [{ title: "Add payout account", detail: "Set a bank or MFS account for settlements", href: "/vendor/payout-settings", icon: "card-outline" as const, urgent: false }] : [])
  ];
  const quickActions = [
    { label: "Add product", href: "/vendor/products/add", icon: "add-circle-outline" as const },
    { label: "Orders", href: "/vendor/orders", icon: "bag-handle-outline" as const, badge: pendingOrders },
    { label: "Inventory", href: "/vendor/inventory", icon: "layers-outline" as const, badge: Number(report.data?.lowStockCount ?? 0) },
    { label: "Finance", href: "/vendor/finance", icon: "wallet-outline" as const },
    { label: "Storefront", href: "/vendor/shop", icon: "storefront-outline" as const },
    { label: "Messages", href: "/vendor/messages", icon: "chatbubbles-outline" as const }
  ];

  return <Screen eyebrow="SELLER CENTER" title={`Welcome back${workspace.data?.displayName ? `, ${workspace.data.displayName}` : ""}`} description="Your live command center for sales, fulfillment, inventory and seller growth.">
    <View style={[styles.hero, compact && styles.heroCompact]}><View style={styles.heroCopy}><Text style={styles.heroLabel}>SELLER WORKSPACE</Text><Text style={[styles.heroTitle, compact && styles.heroTitleCompact]}>{shop?.name || "Your Amiyo-Go shop"}</Text><Text style={styles.heroMeta}>{workspace.data?.status || "LOADING"} · {shop?.status || "DRAFT"} storefront</Text><View style={styles.heroActions}><Pressable onPress={() => router.push("/vendor/products/add")} style={[styles.heroPrimary, compact && styles.heroButtonCompact]}><Ionicons color="#fff" name="add" size={18} /><Text style={styles.primaryText}>Add product</Text></Pressable><Pressable onPress={() => router.push("/vendor/orders")} style={[styles.heroSecondary, compact && styles.heroButtonCompact]}><Text style={styles.heroSecondaryText}>Manage orders</Text></Pressable></View></View><View style={[styles.health, compact && styles.healthCompact]}><Text style={styles.healthLabel}>STORE READINESS</Text><Text style={styles.healthValue}>{readiness}%</Text><View style={styles.track}><View style={[styles.fill, { width: `${readiness}%` }]} /></View><Text style={styles.healthMeta}>{readiness === 100 ? "Ready to grow" : "Complete setup to unlock all tools"}</Text></View></View>
    {workspace.isLoading || report.isLoading ? <ActivityIndicator color={colors.primary} /> : null}
    <View><Text style={styles.quickTitle}>Quick actions</Text><ScrollView contentContainerStyle={styles.quickActions} horizontal showsHorizontalScrollIndicator={false}>{quickActions.map((item) => <Pressable accessibilityLabel={item.label} key={item.href} onPress={() => router.push(item.href as never)} style={({ pressed }) => [styles.quickAction, pressed && styles.pressed]}><View style={styles.quickIcon}><Ionicons color={colors.primary} name={item.icon} size={21} />{item.badge ? <View style={styles.quickBadge}><Text style={styles.quickBadgeText}>{item.badge > 99 ? "99+" : item.badge}</Text></View> : null}</View><Text style={styles.quickLabel}>{item.label}</Text></Pressable>)}</ScrollView></View>
    <View style={styles.metrics}><Metric icon="cash-outline" label="Gross sales" value={formatMinor(report.data?.grossSalesMinor ?? "0")} detail={`${report.data?.periodDays ?? 30}-day revenue`} /><Metric icon="bag-check-outline" label="Total orders" value={String(report.data?.orderCount ?? 0)} detail={`${report.data?.fulfilmentRate ?? 0}% fulfilled`} /><Metric icon="time-outline" label="Active orders" value={String(activeOrders)} detail={`${pendingOrders} need action`} /><Metric icon="alert-circle-outline" label="Low stock" value={String(report.data?.lowStockCount ?? 0)} detail={`${report.data?.productCount ?? 0} live products`} /></View>
    <View style={[styles.columns, compact && styles.columnsCompact]}><View style={styles.main}><Section title="Seller action center" copy="Resolve the highest-priority work first" action="Open operations" onPress={() => router.push("/vendor/operations")} /><View style={styles.panel}>{actions.length ? actions.map((item) => <Pressable key={item.href} onPress={() => router.push(item.href as never)} style={({ pressed }) => [styles.action, pressed && styles.pressed]}><View style={[styles.actionIcon, item.urgent && styles.actionUrgent]}><Ionicons color={item.urgent ? colors.danger : colors.primary} name={item.icon} size={20} /></View><View style={styles.flex}><Text style={styles.actionTitle}>{item.title}</Text><Text style={styles.muted}>{item.detail}</Text></View><Ionicons color={colors.muted} name="chevron-forward" size={18} /></Pressable>) : <Empty />}</View><Section title="Recent orders" copy="Latest orders across your shops" action="View all" onPress={() => router.push("/vendor/orders")} /><View style={styles.panel}>{report.data?.recentOrders.slice(0, 5).map((order) => <Pressable key={order.id} onPress={() => router.push(`/vendor/order/${order.id}` as never)} style={({ pressed }) => [styles.action, compact && styles.orderActionCompact, pressed && styles.pressed]}><View style={styles.orderIcon}><Ionicons color={colors.accent} name="bag-handle-outline" size={20} /></View><View style={styles.flex}><Text style={styles.actionTitle}>{order.orderNumber}</Text><Text numberOfLines={2} style={styles.muted}>{order.itemCount} product line{order.itemCount === 1 ? "" : "s"} · {order.shopName}</Text></View><View style={compact && styles.orderSummaryCompact}><Text style={styles.amount}>{formatMinor(order.totalMinor)}</Text><Text style={styles.status}>{order.status.replaceAll("_", " ")}</Text></View></Pressable>)}{report.data?.recentOrders.length === 0 ? <Empty title="No orders yet" copy="New marketplace orders will appear here." /> : null}</View></View><View style={[styles.side, compact && styles.sideCompact]}><Text style={styles.sectionTitle}>Business setup</Text><View style={styles.panel}>{[{ label: "Seller approval", ready: setup[0], href: "/vendor/settings" }, { label: "Storefront active", ready: setup[1], href: "/vendor/shop" }, { label: "KYC verified", ready: setup[2], href: "/vendor/kyc" }, { label: "Payout account", ready: setup[3], href: "/vendor/payout-settings" }].map((item) => <Pressable key={item.label} onPress={() => router.push(item.href as never)} style={styles.check}><Ionicons color={item.ready ? colors.success : colors.warning} name={item.ready ? "checkmark-circle" : "ellipse-outline"} size={20} /><Text style={styles.checkLabel}>{item.label}</Text><Text style={[styles.checkState, item.ready && styles.ready]}>{item.ready ? "Ready" : "Required"}</Text></Pressable>)}</View><Text style={styles.sectionTitle}>Fulfillment control</Text><View style={styles.fulfillment}><Mini value={activeOrders} label="Active" /><Mini value={report.data?.returnCount ?? 0} label="Returns" /><Mini value={report.data?.cancelledCount ?? 0} label="Cancelled" /></View><Pressable onPress={() => router.push("/vendor/university")} style={({ pressed }) => [styles.learn, pressed && styles.pressed]}><Ionicons color="#E8D7A4" name="school-outline" size={25} /><Text style={styles.learnTitle}>Seller University</Text><Text style={styles.learnCopy}>Learn listing quality, fulfillment and marketplace growth.</Text><Text style={styles.learnLink}>Continue learning →</Text></Pressable></View></View>
  </Screen>;
}

function Metric({ detail, icon, label, value }: { detail: string; icon: React.ComponentProps<typeof Ionicons>["name"]; label: string; value: string }) { return <View style={styles.metric}><View style={styles.metricTop}><View style={styles.metricIcon}><Ionicons color={colors.primary} name={icon} size={21} /></View><Text style={styles.metricLabel}>{label}</Text></View><Text style={styles.metricValue}>{value}</Text><Text style={styles.metricDetail}>{detail}</Text></View>; }
function Section({ action, copy, onPress, title }: { action: string; copy: string; onPress: () => void; title: string }) { return <View style={styles.section}><View><Text style={styles.sectionTitle}>{title}</Text><Text style={styles.sectionMeta}>{copy}</Text></View><Pressable onPress={onPress}><Text style={styles.link}>{action} →</Text></Pressable></View>; }
function Empty({ copy = "No urgent seller tasks need attention.", title = "You are all caught up" }) { return <View style={styles.empty}><Ionicons color={colors.success} name="checkmark-circle-outline" size={30} /><Text style={styles.actionTitle}>{title}</Text><Text style={styles.muted}>{copy}</Text></View>; }
function Mini({ label, value }: { label: string; value: number }) { return <View style={styles.mini}><Text style={styles.miniValue}>{value}</Text><Text style={styles.miniLabel}>{label}</Text></View>; }

const styles = StyleSheet.create({
  hero: { alignItems: "center", backgroundColor: colors.navy, borderRadius: radius.xl, flexDirection: "row", flexWrap: "wrap", gap: spacing.lg, justifyContent: "space-between", padding: spacing.xl }, heroCompact: { alignItems: "stretch", padding: spacing.lg }, heroCopy: { flex: 1, minWidth: 250 }, heroLabel: { color: "#E8D7A4", fontSize: 10, fontWeight: "700", letterSpacing: 1 }, heroTitle: { color: "#FFFDF8", fontSize: 26, fontWeight: "700", marginTop: 9 }, heroTitleCompact: { fontSize: 22 }, heroMeta: { color: "#C9C2B6", marginTop: 6 }, heroActions: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm, marginTop: spacing.lg }, heroPrimary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, flexDirection: "row", gap: 6, minHeight: 44, paddingHorizontal: spacing.md }, heroSecondary: { alignItems: "center", borderColor: "rgba(255,255,255,.32)", borderRadius: radius.md, borderWidth: 1, justifyContent: "center", minHeight: 44, paddingHorizontal: spacing.md }, heroButtonCompact: { flex: 1, minWidth: 130 }, heroSecondaryText: { color: "#fff", fontWeight: "600" }, health: { backgroundColor: "rgba(255,255,255,.1)", borderColor: "rgba(255,255,255,.13)", borderRadius: radius.lg, borderWidth: 1, minWidth: 220, padding: spacing.md }, healthCompact: { minWidth: 0, width: "100%" }, healthLabel: { color: "#C9C2B6", fontSize: 9, fontWeight: "700", letterSpacing: .8 }, healthValue: { color: "#fff", fontSize: 30, fontWeight: "700", marginTop: 4 }, track: { backgroundColor: "rgba(255,255,255,.16)", borderRadius: radius.pill, height: 6, marginTop: spacing.sm, overflow: "hidden" }, fill: { backgroundColor: "#9AAA5B", borderRadius: radius.pill, height: 6 }, healthMeta: { color: "#C9C2B6", fontSize: 10, marginTop: 8 }, quickTitle: { color: colors.text, fontSize: 16, fontWeight: "700", marginBottom: spacing.sm }, quickActions: { gap: spacing.sm, paddingRight: spacing.sm }, quickAction: { alignItems: "center", backgroundColor: colors.surface, borderRadius: radius.lg, gap: spacing.sm, minHeight: 94, padding: spacing.md, width: 104 }, quickIcon: { alignItems: "center", backgroundColor: colors.primarySoft, borderRadius: radius.md, height: 42, justifyContent: "center", position: "relative", width: 42 }, quickBadge: { alignItems: "center", backgroundColor: colors.primary, borderColor: colors.surface, borderRadius: radius.pill, borderWidth: 2, justifyContent: "center", minHeight: 19, minWidth: 19, paddingHorizontal: 4, position: "absolute", right: -8, top: -8 }, quickBadgeText: { color: "#fff", fontSize: 8, fontWeight: "700" }, quickLabel: { color: colors.text, fontSize: 11, fontWeight: "700", textAlign: "center" }, metrics: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, metric: { backgroundColor: colors.surface, borderRadius: radius.lg, boxShadow: "0 8px 24px rgba(11,31,58,.07)", flex: 1, minWidth: 145, padding: spacing.md }, metricTop: { alignItems: "center", flexDirection: "row", gap: spacing.sm }, metricIcon: { alignItems: "center", backgroundColor: colors.primarySoft, borderRadius: radius.md, height: 38, justifyContent: "center", width: 38 }, metricLabel: { color: colors.muted, flex: 1, fontSize: 11, fontWeight: "600" }, metricValue: { color: colors.text, fontSize: 23, fontWeight: "700", marginTop: spacing.md }, metricDetail: { color: colors.muted, fontSize: 10, marginTop: 3 }, columns: { alignItems: "flex-start", flexDirection: "row", gap: spacing.lg }, columnsCompact: { flexDirection: "column" }, main: { flex: 1.7, gap: spacing.md, minWidth: 0, width: "100%" }, side: { flex: 1, gap: spacing.md, minWidth: 280 }, sideCompact: { minWidth: 0, width: "100%" }, section: { alignItems: "flex-end", flexDirection: "row", gap: spacing.md, justifyContent: "space-between" }, sectionTitle: { color: colors.text, fontSize: 18, fontWeight: "700" }, sectionMeta: { color: colors.muted, fontSize: 11, marginTop: 3 }, link: { color: colors.primary, fontSize: 11, fontWeight: "700" }, panel: { backgroundColor: colors.surface, borderRadius: radius.lg, boxShadow: "0 8px 24px rgba(11,31,58,.06)", overflow: "hidden" }, action: { alignItems: "center", borderBottomColor: colors.border, borderBottomWidth: 1, flexDirection: "row", gap: spacing.md, minHeight: 76, padding: spacing.md }, orderActionCompact: { alignItems: "flex-start", flexWrap: "wrap" }, orderSummaryCompact: { marginLeft: 58, width: "100%" }, actionIcon: { alignItems: "center", backgroundColor: colors.primarySoft, borderRadius: radius.md, height: 42, justifyContent: "center", width: 42 }, actionUrgent: { backgroundColor: "#FCE8E6" }, orderIcon: { alignItems: "center", backgroundColor: colors.accentSoft, borderRadius: radius.md, height: 42, justifyContent: "center", width: 42 }, flex: { flex: 1, minWidth: 0 }, actionTitle: { color: colors.text, fontSize: 13, fontWeight: "700" }, muted: { color: colors.muted, fontSize: 10, lineHeight: 16, marginTop: 3 }, amount: { color: colors.text, fontWeight: "700", textAlign: "right" }, status: { color: colors.primary, fontSize: 9, fontWeight: "700", marginTop: 4, textAlign: "right" }, pressed: { opacity: .78, transform: [{ scale: .99 }] }, empty: { alignItems: "center", gap: 4, padding: spacing.xl }, check: { alignItems: "center", borderBottomColor: colors.border, borderBottomWidth: 1, flexDirection: "row", gap: spacing.sm, minHeight: 53, paddingHorizontal: spacing.md }, checkLabel: { color: colors.text, flex: 1, fontSize: 12, fontWeight: "600" }, checkState: { color: colors.warning, fontSize: 9, fontWeight: "700" }, ready: { color: colors.success }, fulfillment: { backgroundColor: colors.surface, borderRadius: radius.lg, boxShadow: "0 8px 24px rgba(11,31,58,.06)", flexDirection: "row", justifyContent: "space-around", padding: spacing.md }, mini: { alignItems: "center", flex: 1 }, miniValue: { color: colors.text, fontSize: 22, fontWeight: "700" }, miniLabel: { color: colors.muted, fontSize: 9, marginTop: 3 }, learn: { backgroundColor: colors.navy, borderRadius: radius.lg, padding: spacing.lg }, learnTitle: { color: "#fff", fontSize: 17, fontWeight: "700", marginTop: spacing.md }, learnCopy: { color: "#C9C2B6", fontSize: 11, lineHeight: 17, marginTop: 5 }, learnLink: { color: "#E8D7A4", fontSize: 11, fontWeight: "700", marginTop: spacing.md }, primary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, padding: spacing.md }, primaryText: { color: "#fff", fontWeight: "700" }
});
